/* 問題探索實驗室｜無框架靜態版。學生資料預設只保存在本機瀏覽器。 */
'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const DB_KEY='diamond-lab-local-v1';
const STEPS=[
  {title:'探索主題',sub:'決定想了解的生活現象',icon:'flag'},
  {title:'探索計畫',sub:'想想要觀察什麼、訪問誰',icon:'search'},
  {title:'訪談紀錄室',sub:'保留受訪者說過的話',icon:'message-square'},
  {title:'觀察紀錄',sub:'記下實際看見的行為',icon:'eye'},
  {title:'整理線索',sub:'用便利貼分類與找出重點',icon:'layers'},
  {title:'Persona 人物誌',sub:'看見有需求的人',icon:'user'},
  {title:'問題陳述',sub:'把真正的問題說清楚',icon:'file-text'},
  {title:'HMW 挑戰',sub:'將問題轉成開放的設計問題',icon:'gem'},
  {title:'成果與反思',sub:'回顧自己的發現與成長',icon:'award'}
];
const KINDS={quote:{label:'受訪者說的話',short:'訪談',cls:'yellow'},observation:{label:'觀察到的事實',short:'觀察',cls:'sky'},guess:{label:'我的推測',short:'猜測',cls:'lavender'}};
const BINS=[{id:'new',label:'待整理'},{id:'behavior',label:'行為與習慣'},{id:'difficulty',label:'困難與痛點'},{id:'need',label:'目標與需求'},{id:'other',label:'其他線索'}];
const CHECKS=[
  '我有說清楚想幫助誰',
  '我有描述具體的情境',
  '我有考慮訪談與觀察中的真正需求',
  '我的問題沒有先限定只能用一種解法',
  '這個問題有機會產生好幾種不同的解法'
];
const now=()=>new Date().toISOString();
const uid=(prefix='id')=>prefix+'_'+((globalThis.crypto&&crypto.randomUUID)?crypto.randomUUID().replaceAll('-','').slice(0,16):Math.random().toString(36).slice(2)+Date.now().toString(36));
function e(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const v=(x)=>e(x).replace(/\n/g,'<br>');
const fmt=(s)=>s?new Date(s).toLocaleString('zh-TW',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'尚未修改';
const dateToday=()=>new Date().toLocaleDateString('sv-SE');
function icon(name,size=''){const icons={
  gem:'<path d="m6 3 12 0 5 6-11 12L1 9z"/><path d="M1 9h22M6 3l-2 6 8 12 8-12-2-6"/>',
  flag:'<path d="M4 22V4m0 0c4-4 8 4 12 0v12c-4 4-8-4-12 0"/>',
  search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 6 6"/>',
  'message-square':'<path d="M4 4h16v13H9l-5 4z"/>',eye:'<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6"/><circle cx="12" cy="12" r="3"/>',
  layers:'<path d="m12 2 10 5-10 5L2 7zM2 12l10 5 10-5M2 17l10 5 10-5"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22c0-5 3-8 8-8s8 3 8 8"/>',
  'file-text':'<path d="M6 2h9l5 5v15H6zM15 2v6h5M9 12h8M9 16h8"/>',award:'<circle cx="12" cy="8" r="6"/><path d="m8 14-2 8 6-3 6 3-2-8"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',
  check:'<path d="m4 12 5 5L20 6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',
  upload:'<path d="M12 21V8m-5 5 5-5 5 5M4 6V3h16v3"/>',monitor:'<rect x="2" y="3" width="20" height="15" rx="2"/><path d="M8 22h8m-4-4v4"/>',
  cloud:'<path d="M6 18H5a4 4 0 0 1 0-8 7 7 0 0 1 14-1 5 5 0 0 1 0 9h-2"/><path d="M12 11v11m-4-4 4 4 4-4"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1.7-2-3.4-2.5 1A7 7 0 0 0 15 6l-.4-3h-4l-.4 3a7 7 0 0 0-1.4.9l-2.5-1-2 3.4L6.3 11A7 7 0 0 0 6 12a7 7 0 0 0 .3 1l-2 1.7 2 3.4 2.5-1a7 7 0 0 0 1.4.9l.4 3h4l.4-3a7 7 0 0 0 1.4-.9l2.5 1 2-3.4-2-1.7z"/>',
  trash:'<path d="M4 7h16M10 3h4l1 4H9zM7 7l1 14h8l1-14M10 11v6m4-6v6"/>',
  edit:'<path d="m4 20 4-1 12-12-3-3L5 16zM15 6l3 3"/>',calendar:'<rect x="3" y="5" width="18" height="17" rx="2"/><path d="M7 2v6M17 2v6M3 10h18"/>',
  users:'<circle cx="9" cy="8" r="3"/><path d="M2 20v-2c0-3 3-5 7-5s7 2 7 5v2M17 5a3 3 0 0 1 0 6m1 3c3 0 4 2 4 4v2"/>',
  book:'<path d="M3 4h7c2 0 2 2 2 2s0-2 2-2h7v15h-7c-2 0-2 2-2 2s0-2-2-2H3zM12 6v15"/>',
  lightbulb:'<path d="M9 18h6m-5 3h4M8 15a7 7 0 1 1 8 0l-1 3H9z"/>',
  close:'<path d="M5 5 19 19M19 5 5 19"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10v1"/>',
  refresh:'<path d="M3 11a9 9 0 0 1 15-6l3 3M21 3v5h-5M21 13a9 9 0 0 1-15 6l-3-3M3 21v-5h5"/>',
  lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
  copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',print:'<path d="M6 9V2h12v7M6 18H3v-9h18v9h-3M6 14h12v8H6z"/>',
  'chevron-down':'<path d="m6 9 6 6 6-6"/>',home:'<path d="m2 11 10-9 10 9M5 10v12h14V10"/>'};return `<span class="icon ${size}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg></span>`;}
function seedClass(){return {id:'class_demo',name:'示範班級',code:'DEMO01',allowCustom:true,reviewCustom:false,topics:[{id:'topic_lunch',title:'校園午餐為什麼常有剩食？',description:'觀察同學用餐的行為、感受與需求，不要先決定解法。'},{id:'topic_queue',title:'校園哪些排隊經驗讓人困擾？',description:'從使用者的角度理解等待與秩序問題。'},{id:'topic_school',title:'同學為什麼經常忘記帶學用品？',description:'了解忘記物品背後的習慣、情境與真實原因。'}]};}
function newState(){return {version:1,updatedAt:now(),classes:[seedClass()],projects:[],settings:{cloudUrl:'',cloudEnabled:false}};}
function makeProject(classId,teamName,mode,topicId,ownTopic,why,members){return {
  id:uid('p'),classId,teamName:teamName.trim(),members:members||'',topicMode:mode,topicId:topicId||'',ownTopic:ownTopic||'',why:why||'',approval:'local',createdAt:now(),updatedAt:now(),recoveryKey:uid('k')+uid('k'),
  plan:{target:'',observation:'',questions:[{id:uid('q'),text:''}]},interviews:[],observations:[],notes:[],
  persona:{name:'',identity:'',background:'',behaviors:'',goals:'',pains:'',needs:'',evidenceIds:[]},
  problem:{user:'',context:'',difficulty:'',reason:'',need:'',custom:''},
  hmw:{who:'',context:'',challenge:'',goal:'',drafts:[],selectedId:'',checks:[false,false,false,false,false]},
  reflection:{before:'',after:'',evidence:'',next:''}
};}
const view={screen:'home',step:0,projectId:null,selectedClassId:'class_demo',teacherClassId:'class_demo',selectedInterview:null,selectedObservation:null,modal:null,form:{},remoteList:[],cloud:'off',cloudMessage:'',storage:'checking'};
let state=newState(),db=null,saveTimer=null,cloudTimer=null,toastTimer=null,cloudPending=null,teacherSecret='';
const getProject=()=>state.projects.find(p=>p.id===view.projectId);
const getClass=(id)=>state.classes.find(c=>c.id===id);
const projectClass=()=>getClass(getProject()?.classId);
const topicName=(p)=>p?.topicMode==='self'?(p.ownTopic||'我的新發現'):(getClass(p.classId)?.topics.find(t=>t.id===p.topicId)?.title||p.topicTitle||'主題已移除');
function setPath(root,path,value){let parts=path.split('.'),node=root;for(let i=0;i<parts.length-1;i++){node=node[parts[i]];if(node==null)return;}node[parts.at(-1)]=value;}
function getPath(root,path){return path.split('.').reduce((v,k)=>v?.[k],root);}
function safeStore(){try{return globalThis.localStorage}catch{return null}}
async function openDB(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(Error('No IndexedDB'));let r=indexedDB.open('diamond-lab',1);r.onupgradeneeded=()=>{let x=r.result;if(!x.objectStoreNames.contains('data'))x.createObjectStore('data')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});}
async function loadIDB(){if(!db)return null;return new Promise(resolve=>{try{let tx=db.transaction('data','readonly'),r=tx.objectStore('data').get('app');r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>resolve(null)}catch{resolve(null)}})}
async function writeIDB(data){if(!db)return false;return new Promise(resolve=>{try{let tx=db.transaction('data','readwrite');tx.objectStore('data').put(data,'app');tx.oncomplete=()=>resolve(true);tx.onerror=()=>resolve(false)}catch{resolve(false)}})}
async function boot(){let a=null,b=null;try{let raw=safeStore()?.getItem(DB_KEY);if(raw)a=JSON.parse(raw)}catch{}try{db=await openDB();b=await loadIDB()}catch{}let chosen=(a&&b)?(String(a.updatedAt)>=String(b.updatedAt)?a:b):(a||b);if(chosen&&Array.isArray(chosen.classes)&&Array.isArray(chosen.projects)){state=chosen;view.storage='ok'}else view.storage=db||safeStore()?'ok':'error';if(!Array.isArray(state.classes)||!state.classes.length)state.classes=[seedClass()];render();}
async function flushSave(){clearTimeout(saveTimer);state.updatedAt=now();let json=JSON.stringify(state);let localOK=false;try{safeStore()?.setItem(DB_KEY,json);localOK=!!safeStore()}catch{}let indexedOK=await writeIDB(state);view.storage=(localOK||indexedOK)?'ok':'error';updateSaveLabel();if(view.storage==='error')toast('瀏覽器未能儲存！請立即匯出備份檔。');}
function touch(){let p=getProject();if(p)p.updatedAt=now();view.storage='saving';if(state.settings.cloudEnabled)view.cloud='pending';updateSaveLabel();clearTimeout(saveTimer);saveTimer=setTimeout(()=>{flushSave();if(state.settings.cloudEnabled&&p)queueCloudSave(p)},380);}
function updateSaveLabel(){let el=$('[data-save-status]');if(!el)return;let status=view.storage==='saving'?['wait','正在寫入本機…']:view.storage==='error'?['error','儲存失敗，請下載備份']:['','已儲存在此瀏覽器'];el.innerHTML=`<span class="dot ${status[0]}"></span>${status[1]}`;let cloud=$('[data-cloud-status]');if(cloud&&state.settings.cloudEnabled)cloud.textContent=view.cloud==='saved'?'雲端已確認同步':view.cloud==='syncing'?'雲端同步中…':view.cloud==='error'?'雲端失敗（本機仍保留）':'雲端等待同步';}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function download(filename,content,type='application/json;charset=utf-8'){let url=URL.createObjectURL(new Blob([content],{type}));let a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1800);}
function exportAll(){download(`問題探索實驗室_完整備份_${dateToday()}.json`,JSON.stringify({kind:'diamond-lab-backup',version:1,date:now(),data:state},null,2));toast('已下載備份，請保管好檔案。')}
function exportOne(p){download(`問題探索_${p.teamName}_${dateToday()}.json`,JSON.stringify({kind:'diamond-lab-project',version:1,date:now(),project:p},null,2));}
function status(p){if(!p)return 0;const done=[!!topicName(p),!!p.plan.target&&p.plan.questions.some(x=>x.text.trim()),p.interviews.some(x=>x.text.trim().length>5),p.observations.some(x=>x.fact.trim()),p.notes.some(x=>x.category!=='new'),!!p.persona.name&&!!p.persona.needs,!!p.problem.user&&!!p.problem.need,p.hmw.drafts.length>0&&!!p.hmw.selectedId,!!p.reflection.after];return done;}
function doneCount(p){return status(p).filter(Boolean).length;}
function htmlButton(action,label,cls='secondary',data=''){return `<button type="button" class="button ${cls}" data-action="${action}" ${data}>${label}</button>`;}
function inputField(label,path,placeholder='',kind='text',hint=''){const val=getPath({project:getProject(),state,form:view.form},path)||'';return `<div class="field"><label>${label}</label>${kind==='textarea'?`<textarea data-bind="${e(path)}" placeholder="${e(placeholder)}">${e(val)}</textarea>`:`<input data-bind="${e(path)}" type="${kind}" placeholder="${e(placeholder)}" value="${e(val)}">`}${hint?`<span class="help">${hint}</span>`:''}</div>`;}
function heading(k,help){return `<div class="page-heading"><div><div class="tagline">DISCOVER · DEFINE ｜ 第 ${k+1} / ${STEPS.length} 站</div><h1>${STEPS[k].title}</h1><p>${help||STEPS[k].sub}</p></div><span class="pill blue">第一顆鑽石</span></div>`;}
function tip(text){return `<div class="tip">${icon('lightbulb','s')} <strong>探索提示</strong>　${text}</div>`;}
function pageActions(step){return `<div class="page-actions"><div>${step>0?htmlButton('prev',`${icon('back','s')} 上一關`,'secondary'):''}</div><div class="button-row">${step<STEPS.length-1?htmlButton('next',`下一關 ${icon('arrow','s')}`,''):htmlButton('print',`${icon('print','s')} 列印成果`,'dark')}${htmlButton('export-project',`${icon('download','s')} 備份我的作品`,'secondary')}</div></div>`;}
function render(){const root=$('#app');if(!root)return;root.innerHTML=view.screen==='home'?home():view.screen==='teacher'?teacher():view.screen==='settings'?settings():view.screen==='workspace'&&getProject()?workspace():home();if(view.modal)root.insertAdjacentHTML('beforeend',modal());updateSaveLabel();}
function brand(){return `<div class="brand"><div class="brand-icon">${icon('gem','l')}</div><span>問題探索實驗室</span></div>`;}
function diamondArt(){return `<div class="hero-art"><span class="float-label a">🔎 同理觀察</span><div class="diamond-drawing"><svg viewBox="0 0 340 250" role="img" aria-label="第一顆鑽石：從探索發散到問題定義收斂"><defs><linearGradient id="dg" x1="0" x2="1"><stop offset="0" stop-color="#b1d9ef"/><stop offset=".5" stop-color="#dcecf6"/><stop offset="1" stop-color="#f6dcc0"/></linearGradient></defs><path d="M23 124 170 22 317 124 170 228Z" stroke="#438caf" stroke-width="3" fill="url(#dg)"/><path d="M170 22V228" stroke="#588eab" stroke-dasharray="5 6" stroke-width="2"/><circle cx="23" cy="124" r="8" fill="#3984ae"/><circle cx="317" cy="124" r="8" fill="#ed995c"/><text x="98" y="128" font-size="17" text-anchor="middle" fill="#296b92" font-weight="bold">發 散</text><text x="242" y="128" font-size="17" text-anchor="middle" fill="#b46a3d" font-weight="bold">收 斂</text></svg></div><span class="float-label b">💡 找到真需求</span></div>`;}
function home(){const classOptions=state.classes.map(c=>`<option value="${e(c.id)}" ${view.selectedClassId===c.id?'selected':''}>${e(c.name)}（${e(c.code)}）</option>`).join('');const cls=getClass(view.selectedClassId)||state.classes[0];const projects=state.projects.filter(p=>p.classId===cls.id);
return `<main class="welcome"><header class="welcome-header">${brand()}<div class="button-row">${htmlButton('go-teacher',`${icon('users','s')} 教師管理`,'secondary')}${htmlButton('go-settings',`${icon('settings','s')} 儲存設定`,'secondary')}</div></header><section class="welcome-hero"><div class="copy"><span class="eyebrow">DESIGN THINKING · DOUBLE DIAMOND</span><h1>好的解答，<br>從<span style="color:#397eaf">真正的問題</span>開始。</h1><p class="lead">用訪談、觀察、電子便利貼與思考工具，一步步走完設計思考的第一顆鑽石，完成你自己的 HMW 設計挑戰。</p><div class="button-row">${htmlButton('start-new',`開始新的探索 ${icon('arrow','s')}`,'')}${htmlButton('show-guide',`${icon('book','s')} 看看使用說明`,'secondary')}</div><p class="help" style="margin-top:14px">📌 本機儲存已啟用；第一次使用請先了解備份說明。</p></div>${diamondArt()}</section>
<section class="welcome-bottom stack"><div class="section-head"><h2>繼續我的探索</h2><span class="pill">同一台電腦可接續</span></div><div class="card stack"><div class="two-col"><div class="field"><label>選擇班級</label><select data-ui="selectedClassId">${classOptions}</select></div><div class="field"><label>班級代碼</label><div style="padding:12px 14px;border:1px dashed #cbd9e2;border-radius:10px;background:#f8fbfd;font-weight:800">${e(cls.code)}</div></div></div><div class="stack sm">${projects.length?projects.map(p=>`<div class="list-record"><div class="button-row" style="justify-content:space-between"><div><h3>${e(p.teamName)}</h3><p>${e(topicName(p))} · ${doneCount(p)}/${STEPS.length} 站 · ${fmt(p.updatedAt)}</p></div>${htmlButton('open-project',`繼續探索 ${icon('arrow','s')}`,'tiny',`data-id="${e(p.id)}"`)}</div><div class="progress">${status(p).map(x=>`<span class="${x?'done':''}"></span>`).join('')}</div></div>`).join(''):`<div class="empty">這個班級還沒有探索作品。<br>按「開始新的探索」就能建立第一份作品。</div>`}</div></div>
<div class="three-col"><div class="feature"><div class="feature-icon">${icon('message-square','l')}</div><h3>訪談紀錄室</h3><p class="muted small">逐字記下真實的聲音，一鍵將重要句子做成線索便利貼。</p></div><div class="feature"><div class="feature-icon">${icon('layers','l')}</div><h3>看得見的思考</h3><p class="muted small">整理線索、建立 Persona、清楚定義問題，再提出 HMW。</p></div><div class="feature"><div class="feature-icon">${icon('download','l')}</div><h3>備份你的努力</h3><p class="muted small">編輯時自動本機儲存，也能匯出 JSON 備份、列印成果。</p></div></div>
<div class="notice">${icon('info','s')} 教師管理是<strong>本機教學展示介面</strong>，並非安全登入系統；同一瀏覽器的使用者可能看到這裡的作品。請使用化名，不要輸入敏感個資。</div></section></main>`;}
function workspace(){let p=getProject(),c=projectClass();let k=view.step;let navigation=STEPS.map((s,i)=>`<button class="step-link ${k===i?'active':''} ${status(p)[i]?'complete':''}" data-action="go-step" data-step="${i}"><span class="num">${status(p)[i]?icon('check','s'):String(i+1).padStart(2,'0')}</span><span>${s.title}</span></button>`).join('');return `<div class="shell"><aside class="sidebar">${brand()}<div class="project-id"><div class="small muted">目前探索小組</div><div class="bold">${e(p.teamName)}</div><div class="small muted">${e(c?.name||'未分類')} · ${e(topicName(p))}</div><div class="progress">${status(p).map((x,i)=>`<span class="${k===i?'now':x?'done':''}"></span>`).join('')}</div><div class="steps">${navigation}</div><div class="sidebar-bottom">${htmlButton('go-home',`${icon('home','s')} 返回首頁`,'secondary full')}<div class="help">你的輸入會自動儲存；建議每節課下載備份。</div></div></aside><div class="main"><header class="topbar"><span class="small muted tiny-hide">設計思考 · Discover → Define</span><div class="statusbar"><span data-save-status class="inline-status"><span class="dot"></span>已儲存在此瀏覽器</span>${state.settings.cloudEnabled?`<span data-cloud-status class="pill">雲端等待同步</span>`:''}${htmlButton('go-home',`${icon('home','s')} 首頁`,'secondary tiny')}</div></header><main class="content">${renderStep(k,p)}${pageActions(k)}</main>${renderPrintReport(p)}</div></div>`;}
function renderStep(k,p){switch(k){case 0:return stepTopic(p);case 1:return stepPlan(p);case 2:return stepInterviews(p);case 3:return stepObservations(p);case 4:return stepNotes(p);case 5:return stepPersona(p);case 6:return stepProblem(p);case 7:return stepHmw(p);case 8:return stepResults(p);default:return '';}}
function stepTopic(p){let c=projectClass(),t=c?.topics.find(x=>x.id===p.topicId);return `${heading(0,'選擇老師準備的挑戰，或從自己的生活開始發現問題。')}<div class="stack lg">${tip('先了解現象、找到誰遇到困難；不要現在就決定要製作 APP、遊戲或產品。')}<div class="card stack"><div class="section-head"><h3>我的探索來源</h3><span class="pill">可以返回修改</span></div><div class="choice-grid"><button class="mode-choice ${p.topicMode==='teacher'?'selected':''}" data-action="choose-mode" data-mode="teacher"><span class="symbol">📋</span><span class="big">老師的挑戰</span><span class="muted">使用老師已準備好的生活情境。</span></button><button class="mode-choice ${p.topicMode==='self'?'selected':''}" data-action="choose-mode" data-mode="self"><span class="symbol">🔎</span><span class="big">我的新發現</span><span class="muted">從真實生活中選一個想研究的現象。</span></button></div></div>${p.topicMode==='teacher'?`<div class="card stack"><h3>選擇一個主題</h3>${(c?.topics||[]).map(t=>`<button class="topic-choice ${p.topicId===t.id?'selected':''}" data-action="choose-topic" data-id="${e(t.id)}"><div class="topic-title">${p.topicId===t.id?'◉':'○'} ${e(t.title)}</div><p>${e(t.description)}</p></button>`).join('')||'<div class="empty">老師還沒有設定主題，請先在教師管理新增。</div>'}</div>`:`<div class="card stack"><h3>我注意到的生活現象</h3>${inputField('我想探索什麼？','project.ownTopic','例如：下課時，飲水機前常常排很長的隊伍','textarea')}${inputField('我為什麼對這件事好奇？','project.why','因為我發現……','textarea')}</div>`}<div class="card soft"><h3>我現在要探索的問題</h3><p style="margin-top:7px;font-size:20px;font-weight:800;color:#2c719e" id="topic-preview">${e(topicName(p))}</p><p class="help" style="margin-top:8px">${p.topicMode==='teacher'?e(t?.description||'可以先從他人的真實經驗開始。'):'先把看到的現象寫清楚，不必急著找答案。'}</p></div></div>`;}
function stepPlan(p){return `${heading(1,'在觀察與訪談之前，先想一想要了解誰，以及要如何探索。')}<div class="stack lg">${tip('比起問「你是不是很懶惰？」，試試問「你平常怎麼做？那時候發生什麼事？」讓對方說出真實經驗。')}<div class="card stack">${inputField('我想了解哪些人？','project.plan.target','例如：平常會把午餐剩下的同學','textarea')}${inputField('我要觀察的情境與行為','project.plan.observation','例如：午餐時間，他們如何選擇食物、何時會剩下……','textarea')}</div><div class="card stack"><div class="section-head"><h3>我的訪談提問清單</h3>${htmlButton('add-question',`${icon('plus','s')} 新增問題`,'secondary tiny')}</div>${p.plan.questions.map((q,i)=>`<div class="field" key="${e(q.id)}"><div class="button-row" style="justify-content:space-between"><label>問題 ${i+1}</label>${htmlButton('delete-question',`${icon('trash','s')} 移除`,'danger tiny',`data-id="${e(q.id)}"`)}</div><textarea data-bind="project.plan.questions.${i}.text" placeholder="例如：你上一次遇到這個問題，是什麼時候？">${e(q.text)}</textarea></div>`).join('')}<div class="notice"><strong>好問題的線索：</strong>能讓對方分享經驗、行為、想法與感受，而不是只能回答「是／不是」。</div></div><div class="card soft"><h3>下一步要做什麼？</h3><p class="muted">帶著這些問題去觀察、訪談，之後在「訪談紀錄室」保留逐字稿，也可以先在紙上寫完再貼上來。</p></div></div>`;}
function stepInterviews(p){const current=p.interviews.find(i=>i.id===view.selectedInterview)||p.interviews[0];if(current&&!view.selectedInterview)view.selectedInterview=current.id;let index=p.interviews.indexOf(current);return `${heading(2,'一位受訪者一份紀錄，保留他真正說過的話。')}<div class="stack lg">${tip('請使用「受訪者 A」等代稱。寫下受訪者原本的語句，不要偷偷改成自己的推測；訪談前記得取得同意。')}<div class="split"><div class="card stack sm"><div class="section-head"><h3>訪談清單</h3>${htmlButton('add-interview',`${icon('plus','s')} 新增`,'tiny')}</div><div class="record-list">${p.interviews.length?p.interviews.map(x=>`<button class="list-record ${current?.id===x.id?'selected':''}" style="text-align:left" data-action="select-interview" data-id="${e(x.id)}"><h4>${e(x.person||'未命名訪談')}</h4><p>${e(x.date||'未填日期')} · ${x.text.length} 字</p></button>`).join(''):'<div class="empty">還沒有訪談資料<br>按「新增」開始記錄</div>'}</div></div><div class="card stack">${current?`<div class="section-head"><h3>編輯訪談紀錄</h3>${htmlButton('delete-interview',`${icon('trash','s')} 刪除此份`,'danger tiny',`data-id="${e(current.id)}"`)}</div><div class="two-col"><div class="field"><label>受訪者代稱</label><input data-bind="project.interviews.${index}.person" value="${e(current.person)}" placeholder="例如：受訪者 A"></div><div class="field"><label>訪談日期</label><input data-bind="project.interviews.${index}.date" type="date" value="${e(current.date)}"></div></div><div class="field"><label>地點／情境（選填）</label><input data-bind="project.interviews.${index}.place" value="${e(current.place)}" placeholder="例如：午餐後的教室"></div><div class="field"><label>訪談逐字稿／訪談內容</label><textarea class="editor" data-interview-editor="${e(current.id)}" data-bind="project.interviews.${index}.text" placeholder="Q：你上次遇到這個問題是什麼時候？&#10;A：……">${e(current.text)}</textarea><span class="help">可以直接在這裡輸入，也可以貼上在其他地方完成的逐字稿。</span></div><div class="button-row">${htmlButton('quote-selection',`${icon('plus','s')} 選取文字 → 製作線索便利貼`,'soft',`data-id="${e(current.id)}"`)}${htmlButton('copy-interview',`${icon('copy','s')} 複製全文`,'secondary tiny',`data-id="${e(current.id)}"`)}</div><div class="notice">先用滑鼠選取上方逐字稿中重要的一段話，再按「製作線索便利貼」。系統會保存來源，讓後面建立人物誌時可以回頭確認。</div>`:'<div class="empty">先新增一份訪談，再開始記錄。</div>'}</div></div></div>`;}
function stepObservations(p){let ob=p.observations.find(x=>x.id===view.selectedObservation)||p.observations[0];if(ob&&!view.selectedObservation)view.selectedObservation=ob.id;let index=p.observations.indexOf(ob);return `${heading(3,'記下實際發生的事情，不要把猜測當成事實。')}<div class="stack lg">${tip('「小明把菜倒掉」是觀察；「小明很挑食」是推測。兩者都可以記錄，但要清楚區分。')}<div class="split"><div class="card stack sm"><div class="section-head"><h3>觀察清單</h3>${htmlButton('add-observation',`${icon('plus','s')} 新增`,'tiny')}</div><div class="record-list">${p.observations.length?p.observations.map(x=>`<button class="list-record ${ob?.id===x.id?'selected':''}" style="text-align:left" data-action="select-observation" data-id="${e(x.id)}"><h4>${e(x.place||'未命名觀察')}</h4><p>${e(x.date||'未填日期')} · ${e((x.fact||'尚未填寫').slice(0,30))}</p></button>`).join(''):'<div class="empty">按「新增」開始記錄<br>觀察到的真實事件</div>'}</div></div><div class="card stack">${ob?`<div class="section-head"><h3>觀察紀錄</h3>${htmlButton('delete-observation',`${icon('trash','s')} 刪除此份`,'danger tiny',`data-id="${e(ob.id)}"`)}</div><div class="two-col"><div class="field"><label>觀察日期</label><input type="date" data-bind="project.observations.${index}.date" value="${e(ob.date)}"></div><div class="field"><label>地點／情境</label><input data-bind="project.observations.${index}.place" value="${e(ob.place)}" placeholder="例如：午餐時間的教室"></div></div><div class="field"><label>我實際看到、聽到什麼？</label><textarea data-bind="project.observations.${index}.fact" placeholder="描述可以被其他人看到或聽到的事情">${e(ob.fact)}</textarea></div><div class="field"><label>我想到的可能原因（只是猜測）</label><textarea data-bind="project.observations.${index}.inference" placeholder="例如：我猜可能是……；還需要訪談確認">${e(ob.inference)}</textarea></div><div class="button-row">${htmlButton('observation-note',`${icon('plus','s')} 將觀察事實做成便利貼`,'soft',`data-id="${e(ob.id)}"`)}${htmlButton('observation-guess-note','將推測做成另一張便利貼','secondary',`data-id="${e(ob.id)}"`)}</div>`:'<div class="empty">請先建立一份觀察紀錄。</div>'}</div></div></div>`;}
function noteCard(n,p,controls=true){return `<div class="sticky ${KINDS[n.type]?.cls||'sky'}" draggable="${controls?'true':'false'}" data-note-id="${e(n.id)}"><div class="note-cat">${e(KINDS[n.type]?.label||'線索')}</div><div class="note-text">${e(n.text)}</div><div class="note-source">${e(sourceLabel(n,p))}</div>${controls?`<div class="foot"><select aria-label="線索分類" data-note-category="${e(n.id)}">${BINS.map(x=>`<option value="${x.id}" ${n.category===x.id?'selected':''}>${x.label}</option>`).join('')}</select><button title="刪除便利貼" data-action="delete-note" data-id="${e(n.id)}">${icon('trash','s')}</button></div>`:''}</div>`;}
function sourceLabel(n,p){if(n.sourceType==='interview')return '來源：'+(p.interviews.find(i=>i.id===n.sourceId)?.person||'訪談（原始資料已刪除）');if(n.sourceType==='observation')return '來源：觀察紀錄';return '來源：自行新增';}
function stepNotes(p){return `${heading(4,'讓每一個發現變成可以整理的線索，觀察共同的困難和需求。')}<div class="stack lg">${tip('先分類，再想這些線索代表什麼。相似的線索可以放在一起；用訪談證據支持你的結論。')}<div class="card stack"><div class="section-head"><h3>新增便利貼</h3><span class="pill">${p.notes.length} 張線索</span></div><div class="two-col"><div class="field"><label>線索類型</label><select data-ui="noteType" id="noteType"><option value="quote">受訪者說的話</option><option value="observation">觀察到的事實</option><option value="guess">我的推測</option></select></div><div class="field"><label>放在哪一組</label><select id="noteBin">${BINS.map(x=>`<option value="${x.id}">${x.label}</option>`).join('')}</select></div></div><div class="field"><label>便利貼內容</label><textarea id="newNoteText" placeholder="一次只記錄一件發現，之後比較容易整理。"></textarea></div>${htmlButton('add-note',`${icon('plus','s')} 加入線索牆`,'')}</div><div class="card stack"><div class="section-head"><h3>線索分類牆</h3><span class="small muted">電腦可以拖曳，手機可用下拉選單分類</span></div><div class="two-col">${BINS.map(bin=>`<div class="group-bin" data-bin="${bin.id}"><div class="section-head"><strong>${e(bin.label)}</strong><span class="pill">${p.notes.filter(n=>n.category===bin.id).length}</span></div>${p.notes.filter(n=>n.category===bin.id).map(n=>noteCard(n,p)).join('')||'<p class="help">把相似的線索放在這裡</p>'}</div>`).join('')}</div></div><div class="card stack"><h3>從線索中找到的發現</h3><p class="muted">當你發現多個人有類似困難，記得思考：背後可能有什麼需要？接下來到「人物誌」整理使用者的需求。</p></div></div>`;}
function stepPersona(p){let pa=p.persona;return `${heading(5,'根據訪談與觀察，為一群有類似需求的人建立代表性人物。')}<div class="stack lg">${tip('Persona 不是憑空創作的角色。請盡量使用上一關的線索，支持人物的行為、困難與需求。缺乏證據就先標記需要再確認。')}<div class="card stack"><div class="section-head"><h3>人物誌製作器</h3><span class="pill">用代稱保護隱私</span></div><div class="two-col">${inputField('人物名稱（代稱）','project.persona.name','例如：小安')}${inputField('他是誰？','project.persona.identity','例如：國中一年級學生')}</div>${inputField('背景與平常生活','project.persona.background','他的生活環境、常見情境……','textarea')}<div class="two-col">${inputField('平常行為與習慣','project.persona.behaviors','訪談與觀察中發現的行為','textarea')}${inputField('他的目標','project.persona.goals','他希望達成什麼？','textarea')}</div><div class="two-col">${inputField('遇到的困難與痛點','project.persona.pains','哪些事情讓他不方便？','textarea')}${inputField('真正需要什麼？','project.persona.needs','他需要改善的是什麼？','textarea')}</div><div class="hr"></div><h3>這個人物誌的資料根據</h3><p class="help">點選與這個人物有關的線索，當作人物誌的證據；這些連結也會出現在成果報告。</p>${p.notes.length?`<div class="stack sm">${p.notes.map(n=>`<label class="toggle-row"><input type="checkbox" data-evidence="${e(n.id)}" ${pa.evidenceIds.includes(n.id)?'checked':''}><span>${e(n.text.slice(0,110))}<span class="help"> · ${e(KINDS[n.type]?.short)}</span></span></label>`).join('')}</div>`:'<div class="notice">還沒有便利貼。建議先返回「整理線索」再開始製作人物誌。</div>'}</div><div class="persona-card"><div class="button-row"><div class="persona-avatar">👤</div><div><div class="eyebrow">PERSONA / 人物誌</div><h2 id="persona-preview-name">${e(pa.name||'尚未命名')}</h2><p class="muted" id="persona-preview-identity">${e(pa.identity||'他是誰？')}</p></div></div><div class="two-col" style="margin-top:17px"><div><b>他希望……</b><p>${v(pa.goals||'尚未填寫')}</p></div><div><b>但遇到……</b><p>${v(pa.pains||'尚未填寫')}</p></div></div><div class="hr"></div><b>真正的需求</b><p id="persona-preview-needs">${v(pa.needs||'尚未填寫')}</p></div></div>`;}
function makeProblem(p){const x=p.problem;return `對於${x.user||'〔使用者〕'}而言，在${x.context||'〔具體情境〕'}，他／她${x.difficulty||'〔遇到的困難〕'}，因為${x.reason||'〔背後原因〕'}，因此需要${x.need||'〔真正需求〕'}。`}
function stepProblem(p){return `${heading(6,'把人物、情境、困難、原因與真正需求連成一段清楚的問題陳述。')}<div class="stack lg">${tip('這一關要回答「真正的問題是什麼」，還不要寫「我們要製作哪個工具」。')}<div class="card stack"><div class="section-head"><h3>五個關鍵問題</h3>${htmlButton('problem-prefill',`${icon('refresh','s')} 從人物誌帶入`,'soft tiny')}</div>${inputField('① 誰遇到問題？','project.problem.user','例如：像小安這樣午餐時間較匆忙的國中生')}${inputField('② 在什麼情境？','project.problem.context','例如：學校午餐時間')}${inputField('③ 遇到什麼困難？','project.problem.difficulty','例如：經常吃不完午餐','textarea')}${inputField('④ 為什麼會發生？','project.problem.reason','例如：用餐時間與個人的步調不太相符','textarea','注意：這個原因最好有訪談或觀察證據支持。')}${inputField('⑤ 他真正需要什麼？','project.problem.need','例如：能依自己的情況更從容地完成用餐','textarea')}</div><div class="card stack soft"><h3>我的問題陳述</h3><div id="problem-preview" class="answer-preview">${e(makeProblem(p))}</div><p class="help">改動上面的內容，這個句子也會跟著更新。</p></div><div class="card stack">${inputField('我想再修飾的版本（選填）','project.problem.custom','如果你希望句子更自然，可以在這裡另外寫一版。','textarea')}<p class="help">沒有填寫時，成果報告會使用上面自動組合的版本。</p></div></div>`;}
function buildHmw(p){let h=p.hmw;return `我們如何幫助${h.who||'〔使用者〕'}，在${h.context||'〔具體情境〕'}，克服${h.challenge||'〔困難／痛點〕'}，以便${h.goal||'〔達成需求或目標〕'}？`}
function stepHmw(p){let h=p.hmw;return `${heading(7,'把定義好的問題，轉化成能夠開啟多種想法的設計挑戰。')}<div class="stack lg">${tip('好的 HMW 要夠具體，卻不能直接限制解法。可以先寫 2～3 個版本，再選出最適合的一句。')}<div class="card stack"><div class="section-head"><h3>HMW 組合器</h3>${htmlButton('hmw-prefill',`${icon('refresh','s')} 從問題陳述帶入`,'soft tiny')}</div>${inputField('我們如何幫助誰？','project.hmw.who','例如：容易忘記帶學用品的國中生')}${inputField('在什麼情境？','project.hmw.context','例如：前一天準備隔天的書包時')}${inputField('克服什麼困難或痛點？','project.hmw.challenge','例如：不知道隔天需要哪些用品')}${inputField('以便達成什麼需求或目標？','project.hmw.goal','例如：可以更安心地準備好學用品')}<div class="hmw-line" id="hmw-preview">${e(buildHmw(p))}</div>${htmlButton('add-hmw',`${icon('plus','s')} 把這句加入 HMW 候選清單`,'')}</div><div class="card stack"><div class="section-head"><h3>比較我的 HMW</h3><span class="pill">${h.drafts.length} 個版本</span></div>${h.drafts.length?h.drafts.map((d,i)=>`<div class="draft ${h.selectedId===d.id?'selected':''}"><div class="button-row" style="justify-content:space-between"><strong>版本 ${i+1}</strong><span class="pill ${h.selectedId===d.id?'green':''}">${h.selectedId===d.id?'已選作最終 HMW':'候選句子'}</span></div><textarea data-bind="project.hmw.drafts.${i}.text" rows="3">${e(d.text)}</textarea><div class="button-row">${htmlButton('select-hmw',h.selectedId===d.id?'✓ 已選擇':'選為最後的 HMW',h.selectedId===d.id?'success tiny':'soft tiny',`data-id="${e(d.id)}"`)}${htmlButton('delete-hmw',`${icon('trash','s')} 刪除`,'danger tiny',`data-id="${e(d.id)}"`)}</div></div>`).join(''):'<div class="empty">還沒有 HMW。先使用上面的組合器新增至少一個版本。</div>'}</div><div class="card stack"><h3>HMW 自我檢查</h3><p class="muted">這是你的自我檢查，不是電腦自動評分。若有不確定的項目，可以回去調整 HMW。</p>${CHECKS.map((t,i)=>`<label class="toggle-row"><input type="checkbox" data-hmw-check="${i}" ${h.checks[i]?'checked':''}><span>${e(t)}</span></label>`).join('')}<div class="pill ${h.checks.every(Boolean)?'green':'blue'}">已確認 ${h.checks.filter(Boolean).length} / ${CHECKS.length} 項</div></div></div>`;}
function stepResults(p){let h=p.hmw.drafts.find(d=>d.id===p.hmw.selectedId);return `${heading(8,'完成第一顆鑽石後，回顧從原本猜測到真正理解的思考旅程。')}<div class="stack lg"><div class="success-banner stack"><div class="eyebrow">YOUR FIRST DIAMOND</div><h2>🎉 你已經走到第一顆鑽石的終點！</h2><p>這裡不只是一句 HMW，還包含你一路蒐集的資料、修正的想法與理解他人的過程。</p><p class="pill green" style="width:max-content">完成 ${doneCount(p)} / ${STEPS.length} 項進度</p></div><div class="card stack"><h3>我的探索成果總覽</h3><div class="two-col"><div class="stat"><span class="muted small">訪談紀錄</span><strong>${p.interviews.length}</strong><span class="help">份原始紀錄</span></div><div class="stat"><span class="muted small">觀察紀錄</span><strong>${p.observations.length}</strong><span class="help">次觀察</span></div><div class="stat"><span class="muted small">整理的線索</span><strong>${p.notes.length}</strong><span class="help">張便利貼</span></div><div class="stat"><span class="muted small">HMW 候選</span><strong>${p.hmw.drafts.length}</strong><span class="help">個挑戰版本</span></div></div><div class="hr"></div><div class="field-label">我們探索的主題</div><h3>${e(topicName(p))}</h3><div class="field-label">真正的問題</div><p>${v(p.problem.custom||makeProblem(p))}</p><div class="field-label">我們最後選出的 HMW</div><div class="hmw-line">${h?e(h.text):'還沒選擇最後的 HMW，請回上一關完成。'}</div></div><div class="card stack"><h3>回顧我的思考變化</h3>${inputField('探索以前，我原本以為……','project.reflection.before','最初，我以為問題是……','textarea')}${inputField('探索以後，我現在發現……','project.reflection.after','訪談與觀察改變了我的想法……','textarea')}${inputField('哪一個線索讓我改變想法？','project.reflection.evidence','例如：受訪者 A 提到……','textarea')}${inputField('下一次，我想再了解什麼？','project.reflection.next','如果可以重新探索，我還想……','textarea')}</div><div class="card stack"><h3>保存你的成果</h3><p class="muted">你可以列印完整成果（或在列印畫面選擇另存 PDF），也可以下載 JSON 檔，保留可匯回網站繼續修改的備份。</p><div class="button-row">${htmlButton('print',`${icon('print','s')} 列印／另存 PDF`,'dark')}${htmlButton('export-project',`${icon('download','s')} 下載作品備份`,'secondary')}${htmlButton('export-all','備份這台電腦的全部作品','soft')}</div><div class="warning-box">提醒：只有瀏覽器本機儲存時，清除網站資料、換瀏覽器或換電腦可能找不到作品。請務必下載備份，或由教師另外設定 Google 試算表同步。</div></div></div>`;}
function teacher(){const c=getClass(view.teacherClassId)||state.classes[0];if(!c)return home();let ps=state.projects.filter(p=>p.classId===c.id);return `<div class="shell"><aside class="sidebar">${brand()}<div class="project-id"><div class="small muted">教師工作區</div><strong>班級與主題管理</strong><p class="help">本機展示模式：沒有帳號權限驗證。</p></div><div class="steps">${htmlButton('go-home',`${icon('home','s')} 回到首頁`,'secondary full')}${htmlButton('go-settings',`${icon('settings','s')} 備份與雲端設定`,'secondary full')}</div><div class="sidebar-bottom"><p class="help">只會直接顯示保存在這一個瀏覽器內的作品；跨裝置教師彙整需設定雲端與管理密鑰。</p></div></aside><div class="main"><header class="topbar"><strong>教師管理中心</strong><span data-save-status class="inline-status"></span></header><main class="content stack lg"><div class="page-heading"><div><div class="tagline">TEACHER STUDIO</div><h1>今天要探索什麼？</h1><p>設定挑戰，讓學生有方向地觀察真實世界。</p></div>${htmlButton('add-class',`${icon('plus','s')} 建立班級`,'')}</div><div class="card stack"><div class="section-head"><h3>選擇班級</h3><span class="pill">${state.classes.length} 個班級</span></div><div class="field"><select data-ui="teacherClassId">${state.classes.map(x=>`<option value="${e(x.id)}" ${x.id===c.id?'selected':''}>${e(x.name)}（${e(x.code)}）</option>`).join('')}</select></div><div class="two-col"><div class="stat"><span class="muted small">班級代碼</span><strong style="font-size:23px">${e(c.code)}</strong><span class="help">班級代碼方便辨識，並不是登入密碼</span></div><div class="stat"><span class="muted small">在本機找到的小組作品</span><strong>${ps.length}</strong><span class="help">其他電腦的作品不會自動出現在這裡</span></div></div><div class="button-row">${htmlButton('edit-class','修改班級名稱','secondary tiny')}${c.id!=='class_demo'?htmlButton('delete-class','刪除班級','danger tiny'):''}</div></div><div class="card stack"><div class="section-head"><h3>學生的主題來源</h3><span class="pill blue">兩種模式可並存</span></div><label class="toggle-row"><input type="checkbox" data-class-setting="allowCustom" ${c.allowCustom?'checked':''}><span><b>允許學生自己建立主題</b><span class="help" style="display:block">學生能以校園或日常生活中的現象作為探索起點。</span></span></label><label class="toggle-row"><input type="checkbox" data-class-setting="reviewCustom" ${c.reviewCustom?'checked':''}><span><b>自訂主題先送老師確認</b><span class="help" style="display:block">教師可在這台電腦的管理畫面核准作品；不同裝置之間須先設定雲端彙整。</span></span></label><div class="warning-box">請至少保留一個老師主題，或開放學生自訂主題，讓新小組有題目可選。</div></div><div class="card stack"><div class="section-head"><h3>老師提供的探索主題</h3>${htmlButton('add-topic',`${icon('plus','s')} 新增主題`,'tiny')}</div>${c.topics.length?c.topics.map(t=>`<div class="list-record"><div class="button-row" style="justify-content:space-between"><div style="flex:1;min-width:150px"><h4>${e(t.title)}</h4><p>${e(t.description)}</p></div><div class="button-row">${htmlButton('edit-topic',`${icon('edit','s')} 修改`,'secondary tiny',`data-id="${e(t.id)}"`)}${htmlButton('delete-topic',`${icon('trash','s')} 刪除`,'danger tiny',`data-id="${e(t.id)}"`)}</div></div></div>`).join(''):'<div class="empty">尚未建立老師主題，仍可開放學生自行建立主題。</div>'}</div><div class="card stack"><div class="section-head"><h3>這台電腦上的小組進度</h3><span class="pill">${ps.length} 份作品</span></div>${ps.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>小組</th><th>探索主題</th><th>進度</th><th>最後修改</th><th>操作</th></tr></thead><tbody>${ps.map(p=>`<tr><td><b>${e(p.teamName)}</b>${p.approval==='pending'?'<br><span class="pill warning">待審核</span>':''}</td><td>${e(topicName(p))}</td><td>${doneCount(p)}/${STEPS.length}</td><td>${fmt(p.updatedAt)}</td><td>${htmlButton('teacher-open-project','查看作品','soft tiny',`data-id="${e(p.id)}"`)} ${p.approval==='pending'?htmlButton('approve-project','核准主題','success tiny',`data-id="${e(p.id)}"`):''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">還沒有學生作品。可先回到首頁建立一個小組進行體驗。</div>'}</div><div class="card stack"><div class="section-head"><h3>雲端班級作品查詢（選用）</h3>${state.settings.cloudEnabled?'<span class="pill green">已設定網址</span>':'<span class="pill">尚未設定</span>'}</div><p class="muted small">若已自行部署附帶的 Google Apps Script，教師可以在此輸入管理密鑰，讀取雲端已同步的作品。管理密鑰不會保存到本機。</p><div class="field"><label>管理密鑰（請勿交給學生）</label><input id="teacherSecret" type="password" placeholder="在 Apps Script 中設定的管理密鑰" value="${e(teacherSecret)}"></div><div class="button-row">${htmlButton('teacher-cloud-list',`${icon('cloud','s')} 查詢雲端作品`,'soft')}${htmlButton('go-settings','設定雲端網址','secondary tiny')}</div>${view.remoteList.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>小組</th><th>班級</th><th>最後同步</th><th>操作</th></tr></thead><tbody>${view.remoteList.map(x=>`<tr><td>${e(x.teamName)}</td><td>${e(x.className)}</td><td>${e(x.updatedAt)}</td><td>${htmlButton('teacher-cloud-load','匯入查看','soft tiny',`data-id="${e(x.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:''}</div><div class="button-row">${htmlButton('export-all',`${icon('download','s')} 下載全部本機備份`,'dark')}${htmlButton('import-file',`${icon('upload','s')} 匯入備份檔`,'secondary')}</div></main></div></div>`;}
function settings(){return `<div class="shell"><aside class="sidebar">${brand()}<div class="stack sm">${htmlButton('go-home',`${icon('home','s')} 返回首頁`,'secondary full')}${htmlButton('go-teacher',`${icon('users','s')} 教師管理`,'secondary full')}</div></aside><div class="main"><header class="topbar"><strong>儲存與備份</strong><span data-save-status class="inline-status"></span></header><main class="content stack lg"><div class="page-heading"><div><div class="tagline">SAVE & BACKUP</div><h1>把你的努力好好保存</h1><p>本機自動暫存、手動備份，以及選用的 Google 試算表同步。</p></div></div><div class="card stack"><h3>① 已啟用：本機自動儲存</h3><div class="success-box">編輯文字後會自動保存到目前瀏覽器；重新整理、關閉後重開通常都能接續。</div><p class="muted">本機儲存不等於永久備份。清除網站資料、無痕模式、共用電腦重設、換瀏覽器或換電腦，都可能讓你看不到原本的資料。</p><div class="button-row">${htmlButton('export-all',`${icon('download','s')} 下載完整 JSON 備份`,'dark')}${htmlButton('import-file',`${icon('upload','s')} 匯入備份檔`,'secondary')}</div><div class="notice">每次上課結束請備份一次；備份檔可能包含訪談文字，務必保存在合適的位置。</div></div><div class="card stack"><div class="section-head"><h3>② 選用：Google 試算表雲端同步</h3><span class="pill ${state.settings.cloudEnabled?'green':'warning'}">${state.settings.cloudEnabled?'已啟用（請確認同步狀態）':'尚未連線'}</span></div><p class="muted small">這個網站已附上 Apps Script 範例；需要教師自行在自己的 Google 帳號建立試算表、部署程式，並把部署網址貼在下方。未設定前所有資料都只在本機。</p><div class="field"><label>Apps Script Web App /exec 網址</label><input data-bind="state.settings.cloudUrl" placeholder="https://script.google.com/macros/s/……/exec" value="${e(state.settings.cloudUrl)}" spellcheck="false" autocomplete="off"></div><label class="toggle-row"><input type="checkbox" id="cloudEnabled" ${state.settings.cloudEnabled?'checked':''}><span><b>啟用雲端同步</b><span class="help" style="display:block">只有網址有效且雲端回覆確認後，才能顯示「雲端已同步」。</span></span></label><div class="button-row">${htmlButton('save-cloud-settings',`${icon('check','s')} 儲存雲端設定`,'')}${htmlButton('test-cloud',`${icon('cloud','s')} 測試連線`,'secondary')}</div><div class="warning-box">這是教學原型的 Google 試算表連線方法，靠長的恢復金鑰限制作品存取，並非學校等級的帳號權限系統。訪談請使用化名，不要輸入敏感個資；若學校有正式資安規範，請改用經核准的登入與資料庫。</div></div><div class="card stack"><h3>③ 從另一台電腦恢復雲端作品</h3><p class="muted small">在原本的作品頁面取得「作品 ID 與恢復金鑰」，帶到另一台電腦輸入即可嘗試讀回已成功同步的作品；作品 ID 不等於班級代碼。</p><div class="field"><label>作品 ID</label><input id="restoreId" placeholder="p_……" spellcheck="false"></div><div class="field"><label>恢復金鑰</label><input id="restoreKey" type="password" placeholder="請從原電腦複製的完整金鑰"></div>${htmlButton('cloud-restore',`${icon('cloud','s')} 從雲端恢復作品`,'soft')}</div><div class="card stack"><h3>我的作品恢復資訊</h3>${state.projects.length?state.projects.map(p=>`<div class="list-record"><h4>${e(p.teamName)} · ${e(topicName(p))}</h4><p class="help">ID：<code>${e(p.id)}</code></p><div class="button-row">${htmlButton('copy-recovery',`${icon('copy','s')} 複製作品 ID 與恢復金鑰`,'secondary tiny',`data-id="${e(p.id)}"`)}${htmlButton('export-one',`${icon('download','s')} 下載備份`,'secondary tiny',`data-id="${e(p.id)}"`)}</div></div>`).join(''):'<div class="empty">尚無作品，建立作品後會出現恢復資訊。</div>'}</div></main></div></div>`;}
function modal(){let type=view.modal;if(!type)return '';let f=view.form;let commonHead=(title,desc='')=>`<div class="modal-head"><div><h2>${title}</h2><p class="muted">${desc}</p></div><button class="button tiny secondary" data-action="close-modal" aria-label="關閉">${icon('close','s')}</button></div>`;let content='';
if(type==='new-project'){let cls=getClass(f.classId)||state.classes[0];let options=state.classes.map(c=>`<option value="${e(c.id)}" ${f.classId===c.id?'selected':''}>${e(c.name)}（${e(c.code)}）</option>`).join('');content=`${commonHead('建立新的探索小組','所有學習紀錄會保留在這個小組的作品裡。')}<div class="stack"><div class="field"><label>選擇班級</label><select data-form="classId" data-form-render="1">${options}</select></div><div class="field"><label>小組名稱（建議使用代稱）</label><input data-form="teamName" value="${e(f.teamName||'')}" placeholder="例如：第 3 組、藍色探索隊"></div><div class="field"><label>成員代稱（選填）</label><input data-form="members" value="${e(f.members||'')}" placeholder="例如：1 號、5 號、8 號"></div><div class="field"><label>探索模式</label><div class="choice-grid"><button class="mode-choice ${f.mode==='teacher'?'selected':''}" data-action="form-mode" data-mode="teacher"><strong>📋 老師的挑戰</strong><span class="muted">從主題卡選擇</span></button><button class="mode-choice ${f.mode==='self'?'selected':''}" ${!cls.allowCustom?'disabled':''} data-action="form-mode" data-mode="self"><strong>🔎 自己找問題</strong><span class="muted">從生活現象開始</span></button></div></div>${f.mode==='teacher'?`<div class="field"><label>挑戰主題</label><select data-form="topicId"><option value="">請選擇主題</option>${cls.topics.map(t=>`<option value="${e(t.id)}" ${f.topicId===t.id?'selected':''}>${e(t.title)}</option>`).join('')}</select></div>`:`<div class="field"><label>我注意到的問題現象</label><textarea data-form="ownTopic" placeholder="例如：學校飲水機前排隊很久">${e(f.ownTopic||'')}</textarea></div><div class="field"><label>我想了解這件事，因為……</label><textarea data-form="why" placeholder="先記錄你現在的好奇和猜測">${e(f.why||'')}</textarea></div>`}</div><div class="modal-actions">${htmlButton('close-modal','取消','secondary')}${htmlButton('create-project',`建立探索作品 ${icon('arrow','s')}`,'')}</div>`;}
else if(type==='class'){content=`${commonHead(f.editId?'修改班級':'建立班級','班級代碼只是識別用，不具有密碼保護。')}<div class="stack"><div class="field"><label>班級名稱</label><input data-form="name" value="${e(f.name||'')}" placeholder="例如：六年一班"></div><div class="field"><label>班級代碼</label><input data-form="code" value="${e(f.code||'')}" placeholder="例如：CLASS6A" maxlength="16"></div></div><div class="modal-actions">${htmlButton('close-modal','取消','secondary')}${htmlButton('save-class','儲存班級','')}</div>`;}
else if(type==='topic'){content=`${commonHead(f.editId?'修改探索主題':'新增老師的挑戰','建議描述要探索的現象，不要先指定唯一解決方法。')}<div class="stack"><div class="field"><label>探索主題</label><input data-form="title" value="${e(f.title||'')}" placeholder="例如：為什麼校園午餐經常有剩食？"></div><div class="field"><label>情境說明／探索提醒</label><textarea data-form="description" placeholder="例如：觀察同學什麼時候吃不完，訪問他們的真實經驗……">${e(f.description||'')}</textarea></div></div><div class="modal-actions">${htmlButton('close-modal','取消','secondary')}${htmlButton('save-topic','儲存主題','')}</div>`;}
else if(type==='guide'){content=`${commonHead('探索指南','第一顆鑽石：先發散了解，最後收斂定義。')}<div class="stack">${STEPS.map((s,i)=>`<div class="step-mini"><span class="number">${i+1}</span><div><b>${s.title}</b><p class="help">${s.sub}</p></div></div>`).join('')}<div class="notice">資料會自動保存在這台電腦的瀏覽器中，但請每節課下載一份完整備份。若要換電腦，請使用備份匯入或先設定雲端同步。</div></div><div class="modal-actions">${htmlButton('close-modal','了解了','')}</div>`;}
return `<div class="modal-shade" data-modal-shade="1"><div class="modal" role="dialog" aria-modal="true">${content}</div></div>`;}
function renderPrintReport(p){let h=p.hmw.drafts.find(x=>x.id===p.hmw.selectedId);return `<article class="print-report"><h1>問題探索實驗室｜第一顆鑽石成果</h1><p>小組：${e(p.teamName)}　主題：${e(topicName(p))}　產生日期：${dateToday()}</p><section><h2>一、探索計畫</h2><p>探索對象：${e(p.plan.target)}</p><p>觀察規劃：${e(p.plan.observation)}</p>${p.plan.questions.map((x,i)=>`<p>訪談問題 ${i+1}：${e(x.text)}</p>`).join('')}</section><section><h2>二、原始訪談紀錄</h2>${p.interviews.map(x=>`<div class="print-note"><b>${e(x.person)}　${e(x.date)}　${e(x.place)}</b><pre>${e(x.text)}</pre></div>`).join('')||'<p>尚無紀錄</p>'}</section><section><h2>三、觀察紀錄</h2>${p.observations.map(x=>`<div class="print-note"><b>${e(x.date)}　${e(x.place)}</b><p>事實：${e(x.fact)}</p><p>猜測：${e(x.inference)}</p></div>`).join('')||'<p>尚無紀錄</p>'}</section><section><h2>四、線索整理</h2>${p.notes.map(n=>`<div class="print-note"><b>${e(BINS.find(x=>x.id===n.category)?.label)} · ${e(KINDS[n.type]?.label)}</b><p>${e(n.text)}</p><p class="help">${e(sourceLabel(n,p))}</p></div>`).join('')||'<p>尚無線索</p>'}</section><section><h2>五、Persona 人物誌</h2>${['name','identity','background','behaviors','goals','pains','needs'].map((key,i)=>`<p>${['名稱','身分','背景','行為習慣','目標','痛點','真正需求'][i]}：${e(p.persona[key])}</p>`).join('')}<p>證據：${p.persona.evidenceIds.map(id=>e(p.notes.find(x=>x.id===id)?.text||'')).join('；')}</p></section><section><h2>六、Problem Statement</h2><p>${e(p.problem.custom||makeProblem(p))}</p></section><section><h2>七、HMW 設計挑戰</h2><p><b>${e(h?.text||'尚未完成')}</b></p>${p.hmw.drafts.map((x,i)=>`<p>版本 ${i+1}：${e(x.text)}</p>`).join('')}</section><section><h2>八、反思</h2><p>原本以為：${e(p.reflection.before)}</p><p>現在發現：${e(p.reflection.after)}</p><p>重要線索：${e(p.reflection.evidence)}</p><p>下一步：${e(p.reflection.next)}</p></section></article>`;}
function renderStepWithoutReset(){render();}
function updatePreviews(){let p=getProject();if(!p)return;if($('#problem-preview'))$('#problem-preview').textContent=makeProblem(p);if($('#hmw-preview'))$('#hmw-preview').textContent=buildHmw(p);if($('#topic-preview'))$('#topic-preview').textContent=topicName(p);if($('#persona-preview-name'))$('#persona-preview-name').textContent=p.persona.name||'尚未命名';if($('#persona-preview-identity'))$('#persona-preview-identity').textContent=p.persona.identity||'他是誰？';if($('#persona-preview-needs'))$('#persona-preview-needs').textContent=p.persona.needs||'尚未填寫';}
function addNote(p,type,text,sourceType='',sourceId='',category='new'){if(!text||!text.trim())return toast('請先輸入線索文字。');let content=text.trim();if(content.length>3500){toast('這段文字太長，建議只選取一個重點句子（最多 3500 字）。');return;}p.notes.push({id:uid('n'),type,text:content,sourceType,sourceId,category,createdAt:now()});touch();render();toast('已新增線索便利貼！');}
function saveClass(){const f=view.form;let name=String(f.name||'').trim(),code=String(f.code||'').toUpperCase().replace(/[^A-Z0-9_-]/g,'');if(!name||code.length<4)return toast('請填寫班級名稱，以及至少 4 個字元的英文／數字班級代碼。');if(state.classes.some(c=>c.code===code&&c.id!==f.editId))return toast('這個班級代碼已被使用，請換一個。');if(f.editId){let c=getClass(f.editId);if(c){c.name=name;c.code=code;}}else{let c={id:uid('class'),name,code,allowCustom:true,reviewCustom:false,topics:[]};state.classes.push(c);view.teacherClassId=c.id;view.selectedClassId=c.id;}view.modal=null;touch();render();toast('班級已儲存');}
function saveTopic(){const f=view.form,c=getClass(view.teacherClassId);if(!c)return;let title=String(f.title||'').trim(),description=String(f.description||'').trim();if(!title)return toast('請輸入探索主題。');if(f.editId){let t=c.topics.find(x=>x.id===f.editId);if(t){t.title=title;t.description=description;}}else c.topics.push({id:uid('topic'),title,description});view.modal=null;touch();render();toast('探索主題已儲存');}
function createProject(){const f=view.form,c=getClass(f.classId);if(!c)return toast('請先選擇班級。');let name=String(f.teamName||'').trim();if(!name)return toast('請輸入小組名稱。');if(f.mode==='self'){if(!c.allowCustom)return toast('老師未開放自行建立主題。');if(!String(f.ownTopic||'').trim())return toast('請描述你注意到的生活現象。')}else if(!c.topics.find(x=>x.id===f.topicId))return toast('請選擇老師提供的探索主題。');let p=makeProject(c.id,name,f.mode,f.topicId,f.ownTopic,f.why,f.members);p.topicTitle=f.mode==='teacher'?c.topics.find(x=>x.id===f.topicId)?.title:f.ownTopic;p.className=c.name;p.approval=f.mode==='self'&&c.reviewCustom?'pending':'approved';state.projects.push(p);view.projectId=p.id;view.step=0;view.screen='workspace';view.modal=null;view.selectedInterview=null;view.selectedObservation=null;touch();render();toast('新的探索作品已建立，開始吧！');}
function clickAction(el){let a=el.dataset.action,p=getProject(),id=el.dataset.id;switch(a){
case 'go-home': view.screen='home';view.modal=null;render();return;
case 'go-teacher':view.screen='teacher';view.modal=null;render();return;
case 'go-settings':view.screen='settings';view.modal=null;render();return;
case 'show-guide':view.modal='guide';render();return;
case 'close-modal':view.modal=null;render();return;
case 'start-new':view.form={classId:view.selectedClassId||state.classes[0]?.id,teamName:'',members:'',mode:'teacher',topicId:'',ownTopic:'',why:''};if(!getClass(view.form.classId)?.topics.length&&getClass(view.form.classId)?.allowCustom)view.form.mode='self';view.modal='new-project';render();return;
case 'form-mode':view.form.mode=el.dataset.mode;render();return;
case 'create-project':createProject();return;
case 'open-project':case 'teacher-open-project':view.projectId=id;view.screen='workspace';view.step=a==='teacher-open-project'?8:0;view.selectedInterview=null;view.selectedObservation=null;render();return;
case 'go-step':view.step=+el.dataset.step;render();window.scrollTo({top:0,behavior:'instant'});return;
case 'prev':view.step=Math.max(0,view.step-1);render();window.scrollTo({top:0,behavior:'instant'});return;
case 'next':view.step=Math.min(STEPS.length-1,view.step+1);render();window.scrollTo({top:0,behavior:'instant'});return;
case 'choose-mode':if(!p)return; if(el.dataset.mode==='self'&&!projectClass()?.allowCustom)return toast('老師尚未開放自行建立主題。');p.topicMode=el.dataset.mode;touch();render();return;
case 'choose-topic':if(!p)return;p.topicId=id;p.topicTitle=projectClass()?.topics.find(x=>x.id===id)?.title||'';touch();render();return;
case 'add-question':p.plan.questions.push({id:uid('q'),text:''});touch();render();return;
case 'delete-question':if(p.plan.questions.length<=1)return toast('至少保留一格訪談問題。');p.plan.questions=p.plan.questions.filter(x=>x.id!==id);touch();render();return;
case 'add-interview':{let x={id:uid('interview'),person:`受訪者 ${String.fromCharCode(65+p.interviews.length%26)}`,date:dateToday(),place:'',text:''};p.interviews.push(x);view.selectedInterview=x.id;touch();render();return;}
case 'select-interview':view.selectedInterview=id;render();return;
case 'delete-interview':if(!confirm('確定刪除這份訪談？已從它擷取的便利貼會保留文字，但失去原始紀錄來源。'))return;p.interviews=p.interviews.filter(x=>x.id!==id);view.selectedInterview=p.interviews[0]?.id||null;touch();render();return;
case 'copy-interview':{let x=p.interviews.find(z=>z.id===id);copyText(`訪談：${x.person}\n日期：${x.date}\n\n${x.text}`);return;}
case 'quote-selection':{let x=p.interviews.find(z=>z.id===id),ta=$(`[data-interview-editor="${CSS.escape(id)}"]`);if(!x||!ta)return;let selected=ta.value.slice(ta.selectionStart,ta.selectionEnd).trim();if(!selected)return toast('請先在逐字稿中選取一段重要的話。');addNote(p,'quote',selected,'interview',id);return;}
case 'add-observation':{let x={id:uid('obs'),date:dateToday(),place:'',fact:'',inference:''};p.observations.push(x);view.selectedObservation=x.id;touch();render();return;}
case 'select-observation':view.selectedObservation=id;render();return;
case 'delete-observation':if(!confirm('確定刪除這份觀察紀錄？'))return;p.observations=p.observations.filter(x=>x.id!==id);view.selectedObservation=p.observations[0]?.id||null;touch();render();return;
case 'observation-note':case 'observation-guess-note':{let x=p.observations.find(z=>z.id===id);if(!x)return;addNote(p,a==='observation-note'?'observation':'guess',a==='observation-note'?x.fact:x.inference,'observation',id);return;}
case 'add-note':{let text=$('#newNoteText')?.value,kind=$('#noteType')?.value||'quote',bin=$('#noteBin')?.value||'new';addNote(p,kind,text,'','',bin);return;}
case 'delete-note':if(!confirm('刪除這張便利貼？原本的訪談或觀察文字仍會保留。'))return;p.notes=p.notes.filter(n=>n.id!==id);p.persona.evidenceIds=p.persona.evidenceIds.filter(x=>x!==id);touch();render();return;
case 'problem-prefill':{let pa=p.persona;if(!pa.name&&!pa.identity)return toast('先完成一些人物誌資料，再來帶入。');let has=Object.values(p.problem).some(x=>x.trim());if(has&&!confirm('用人物誌重新帶入，會取代目前的問題陳述欄位。要繼續嗎？'))return;p.problem.user=pa.identity?`像${pa.name||'這位使用者'}這樣的${pa.identity}`:pa.name;p.problem.context=pa.background;p.problem.difficulty=pa.pains;p.problem.reason=pa.behaviors;p.problem.need=pa.needs;p.problem.custom='';touch();render();return;}
case 'hmw-prefill':{let pr=p.problem;if(!pr.user)return toast('請先在前一關完成問題陳述。');if([p.hmw.who,p.hmw.context,p.hmw.challenge,p.hmw.goal].some(x=>x.trim())&&!confirm('重新帶入會覆蓋目前 HMW 組合器的欄位，確定嗎？'))return;p.hmw.who=pr.user;p.hmw.context=pr.context;p.hmw.challenge=pr.difficulty;p.hmw.goal=pr.need;touch();render();return;}
case 'add-hmw':{let h=p.hmw;if(!h.who.trim()||!h.goal.trim())return toast('至少填寫「要幫助誰」與「希望達成的需求」。');let draft={id:uid('hmw'),text:buildHmw(p)};h.drafts.push(draft);if(!h.selectedId)h.selectedId=draft.id;touch();render();toast('新增一個 HMW 候選版本');return;}
case 'select-hmw':p.hmw.selectedId=id;touch();render();return;
case 'delete-hmw':if(!confirm('確定刪除這個 HMW 版本？'))return;p.hmw.drafts=p.hmw.drafts.filter(x=>x.id!==id);if(p.hmw.selectedId===id)p.hmw.selectedId=p.hmw.drafts[0]?.id||'';touch();render();return;
case 'print':window.print();return;
case 'export-project':if(p)exportOne(p);return;
case 'export-one':{let x=state.projects.find(z=>z.id===id);if(x)exportOne(x);return;}
case 'export-all':exportAll();return;
case 'import-file':$('#backupFile')?.click();return;
case 'add-class':view.form={editId:'',name:'',code:uid('').slice(0,8).toUpperCase()};view.modal='class';render();return;
case 'edit-class':{let c=getClass(view.teacherClassId);view.form={editId:c.id,name:c.name,code:c.code};view.modal='class';render();return;}
case 'save-class':saveClass();return;
case 'delete-class':{let c=getClass(view.teacherClassId);if(!c||!confirm(`確定刪除「${c.name}」？這不會刪除小組作品，但作品可能失去班級設定。`))return;state.classes=state.classes.filter(x=>x.id!==c.id);if(!state.classes.length)state.classes.push(seedClass());view.teacherClassId=state.classes[0].id;view.selectedClassId=view.teacherClassId;touch();render();return;}
case 'add-topic':view.form={editId:'',title:'',description:''};view.modal='topic';render();return;
case 'edit-topic':{let t=getClass(view.teacherClassId)?.topics.find(x=>x.id===id);if(!t)return;view.form={editId:t.id,title:t.title,description:t.description};view.modal='topic';render();return;}
case 'save-topic':saveTopic();return;
case 'delete-topic':{let c=getClass(view.teacherClassId),t=c?.topics.find(x=>x.id===id);if(!t||!confirm(`確定刪除主題「${t.title}」？已建立的作品會保留舊題目。`))return;c.topics=c.topics.filter(x=>x.id!==id);touch();render();return;}
case 'approve-project':{let x=state.projects.find(z=>z.id===id);if(x){x.approval='approved';touch();render();toast('已核准主題（只在這台電腦保存）');}return;}
case 'copy-recovery':{let x=state.projects.find(z=>z.id===id);if(x)copyText(`作品 ID：${x.id}\n恢復金鑰：${x.recoveryKey}\n請保密：拿到兩者的人可能取回作品內容。`);return;}
case 'save-cloud-settings':{let url=String(state.settings.cloudUrl||'').trim(),enabled=$('#cloudEnabled')?.checked;if(enabled&&!/^https:\/\/script\.google\.com\/macros\/s\/[^\s]+\/exec(?:\?[^\s]*)?$/.test(url))return toast('請先輸入有效的 Google Apps Script /exec 部署網址。');state.settings.cloudEnabled=!!enabled;view.cloud='off';touch();render();toast(enabled?'已啟用設定；請按「測試連線」驗證。':'已關閉雲端同步。');return;}
case 'test-cloud':testCloud();return;
case 'cloud-restore':restoreCloud();return;
case 'teacher-cloud-list':teacherSecret=$('#teacherSecret')?.value||'';teacherCloudList();return;
case 'teacher-cloud-load':teacherCloudLoad(id);return;
default: console.warn('Unknown action',a);return;
}}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('已複製！')}catch{let ta=document.createElement('textarea');ta.value=s;document.body.append(ta);ta.select();try{document.execCommand('copy');toast('已複製！')}catch{toast('複製失敗，請手動選取。')}ta.remove();}}
function ensureProjectClass(p){if(!getClass(p.classId)){let id=p.classId||uid('class');p.classId=id;state.classes.push({id,name:p.className||'匯入的班級',code:'IMPORT'+Math.floor(Math.random()*9000+1000),allowCustom:true,reviewCustom:false,topics:p.topicId?[{id:p.topicId,title:p.topicTitle||'匯入的探索主題',description:''}]:[]});}}
async function loadBackup(file){if(!file)return;if(file.size>8*1024*1024)return toast('檔案超過 8 MB，請確認備份格式。');let x;try{x=JSON.parse(await file.text())}catch{return toast('不是有效的 JSON 備份檔。')}if(x.kind==='diamond-lab-backup'&&Array.isArray(x.data?.projects)&&Array.isArray(x.data?.classes)){if(!confirm('匯入完整備份會取代這個瀏覽器目前的全部班級與作品！建議先下載現有備份。確定繼續？'))return;state=x.data;state.updatedAt=now();if(!state.settings)state.settings={cloudUrl:'',cloudEnabled:false};view.screen='home';view.projectId=null;view.selectedClassId=state.classes[0]?.id;view.teacherClassId=view.selectedClassId;await flushSave();render();toast('完整備份已還原！')}else if(x.kind==='diamond-lab-project'&&x.project?.id&&x.project?.teamName){let p=x.project;ensureProjectClass(p);let existing=state.projects.find(q=>q.id===p.id);if(existing){if(!confirm(`已有相同作品「${existing.teamName}」。確定覆蓋它嗎？`))return;state.projects=state.projects.filter(q=>q.id!==p.id)}state.projects.push(p);view.projectId=p.id;view.screen='workspace';view.step=8;await flushSave();render();toast('已匯入作品！')}else toast('無法辨識這份備份，請使用網站匯出的 JSON 檔。');}
// Input delegation: typing updates in-memory data; debounce persists locally without replacing focused fields.
document.addEventListener('input',ev=>{let el=ev.target;if(el.dataset.bind){setPath({project:getProject(),state,form:view.form},el.dataset.bind,el.value);touch();updatePreviews();}if(el.dataset.form){view.form[el.dataset.form]=el.value;}if(el.id==='teacherSecret')teacherSecret=el.value;});
document.addEventListener('change',ev=>{let el=ev.target;if(el.dataset.ui){view[el.dataset.ui]=el.value;render();return;}if(el.dataset.form&&el.dataset.formRender){view.form[el.dataset.form]=el.value;if(view.form.mode==='self'&&!getClass(el.value)?.allowCustom)view.form.mode='teacher';view.form.topicId='';render();return;}let p=getProject();if(el.dataset.noteCategory&&p){let n=p.notes.find(x=>x.id===el.dataset.noteCategory);if(n){n.category=el.value;touch();render();}return;}if(el.dataset.evidence&&p){let ids=p.persona.evidenceIds;ids=el.checked?[...new Set([...ids,el.dataset.evidence])]:ids.filter(x=>x!==el.dataset.evidence);p.persona.evidenceIds=ids;touch();return;}if(el.dataset.hmwCheck!=null&&p){p.hmw.checks[+el.dataset.hmwCheck]=el.checked;touch();render();return;}if(el.dataset.classSetting){let c=getClass(view.teacherClassId);c[el.dataset.classSetting]=el.checked;touch();render();return;}});
document.addEventListener('click',ev=>{if(ev.target.matches('[data-modal-shade]')){view.modal=null;render();return;}let el=ev.target.closest('[data-action]');if(el){ev.preventDefault();clickAction(el);}});
document.addEventListener('dragstart',ev=>{let note=ev.target.closest('[data-note-id]');if(note&&ev.dataTransfer){ev.dataTransfer.setData('text/plain',note.dataset.noteId);ev.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',ev=>{let bin=ev.target.closest('[data-bin]');if(bin){ev.preventDefault();bin.classList.add('over');}});
document.addEventListener('dragleave',ev=>{let bin=ev.target.closest('[data-bin]');if(bin&&!bin.contains(ev.relatedTarget))bin.classList.remove('over');});
document.addEventListener('drop',ev=>{let bin=ev.target.closest('[data-bin]'),p=getProject();if(bin&&p){ev.preventDefault();$$('.group-bin').forEach(x=>x.classList.remove('over'));let id=ev.dataTransfer.getData('text/plain'),n=p.notes.find(x=>x.id===id);if(n){n.category=bin.dataset.bin;touch();render();}}});
$('#backupFile')?.addEventListener('change',async ev=>{await loadBackup(ev.target.files?.[0]);ev.target.value='';});
window.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&saveTimer)flushSave();});
window.addEventListener('pagehide',()=>{if(saveTimer){try{safeStore()?.setItem(DB_KEY,JSON.stringify(state))}catch{}}});
// Optional cloud bridge. Google Apps Script HtmlService responds from an iframe with postMessage.
// A confirmed ack is required before showing "cloud synced". No third-party SDK needed.
function cloudRequest(payload){return new Promise((resolve,reject)=>{let url=String(state.settings.cloudUrl||'').trim();if(!/^https:\/\/script\.google\.com\/macros\/s\/[^\s]+\/exec(?:\?[^\s]*)?$/.test(url))return reject(Error('請先設定 Apps Script /exec 網址。'));
  let id=uid('request'),frame=document.createElement('iframe'),form=document.createElement('form');frame.name=id;frame.style.display='none';frame.setAttribute('aria-hidden','true');form.action=url;form.method='POST';form.target=id;form.style.display='none';let input=document.createElement('input');input.type='hidden';input.name='payload';input.value=JSON.stringify({...payload,requestId:id});form.appendChild(input);document.body.append(frame,form);
  let timer,finished=false;function end(err,data){if(finished)return;finished=true;clearTimeout(timer);window.removeEventListener('message',listener);form.remove();frame.remove();err?reject(err):resolve(data)}
  function listener(ev){if(!ev.data||ev.data.kind!=='diamond-lab-cloud'||ev.data.requestId!==id)return;if(ev.origin!=='null'&&!/^https:\/\/(?:[\w.-]+\.)?(?:googleusercontent\.com|google\.com)$/.test(ev.origin))return;let response=ev.data.response;if(response?.ok)end(null,response);else end(Error(response?.error||'雲端服務回傳錯誤'));}
  window.addEventListener('message',listener);timer=setTimeout(()=>end(Error('沒有收到 Google Apps Script 的確認回覆，請檢查部署與網路。')),18000);form.submit();});}
function queueCloudSave(p){if(!state.settings.cloudEnabled||!p)return;view.cloud='pending';updateSaveLabel();clearTimeout(cloudTimer);let id=p.id;cloudTimer=setTimeout(()=>syncProjectCloud(id),2600);}
async function syncProjectCloud(id){if(!state.settings.cloudEnabled)return;let p=state.projects.find(x=>x.id===id);if(!p)return;let snapshot=JSON.parse(JSON.stringify(p)),c=getClass(p.classId);view.cloud='syncing';updateSaveLabel();try{let response=await cloudRequest({action:'save',project:snapshot,recoveryKey:snapshot.recoveryKey,className:c?.name||snapshot.className||'',classCode:c?.code||'',topicTitle:topicName(p)});if(response.ok){let current=state.projects.find(x=>x.id===id);view.cloud=current?.updatedAt===snapshot.updatedAt?'saved':'pending';if(current?.updatedAt!==snapshot.updatedAt)queueCloudSave(current);}}catch(err){view.cloud='error';console.error('cloud sync',err);toast('雲端未確認同步；資料仍會留在本機。請檢查雲端設定。');}updateSaveLabel();}
async function testCloud(){view.cloud='syncing';updateSaveLabel();try{let res=await cloudRequest({action:'ping'});view.cloud='saved';toast(`雲端連線成功：${res.message||'Apps Script 已回覆'}`)}catch(err){view.cloud='error';toast('測試失敗：'+err.message)}updateSaveLabel();}
async function restoreCloud(){let id=$('#restoreId')?.value.trim(),key=$('#restoreKey')?.value.trim();if(!id||!key)return toast('請輸入作品 ID 和完整的恢復金鑰。');try{let res=await cloudRequest({action:'load',projectId:id,recoveryKey:key});let p=res.project;if(!p||!p.id||!p.teamName)throw Error('雲端未回傳有效作品');ensureProjectClass(p);let old=state.projects.find(x=>x.id===p.id);if(old&&!confirm(`本機已有作品「${old.teamName}」，要用雲端版本覆蓋嗎？`))return;state.projects=state.projects.filter(x=>x.id!==p.id);state.projects.push(p);view.screen='workspace';view.projectId=p.id;view.step=8;await flushSave();render();toast('已成功從雲端恢復作品！')}catch(err){toast('雲端恢復失敗：'+err.message)}}
async function teacherCloudList(){if(!teacherSecret)return toast('請先輸入教師管理密鑰。');try{let res=await cloudRequest({action:'teacherList',adminSecret:teacherSecret});view.remoteList=Array.isArray(res.projects)?res.projects:[];render();toast(`已查詢到 ${view.remoteList.length} 個雲端作品`)}catch(err){toast('雲端查詢失敗：'+err.message)}}
async function teacherCloudLoad(id){try{let res=await cloudRequest({action:'teacherLoad',adminSecret:teacherSecret,projectId:id});let p=res.project;if(!p?.id)throw Error('找不到作品');ensureProjectClass(p);let old=state.projects.find(x=>x.id===p.id);if(old&&!confirm('本機已有這份作品。要用雲端版本覆蓋嗎？'))return;state.projects=state.projects.filter(x=>x.id!==p.id);state.projects.push(p);view.screen='workspace';view.projectId=p.id;view.step=8;await flushSave();render();toast('已將雲端作品匯入目前瀏覽器')}catch(err){toast('讀取雲端作品失敗：'+err.message)}}
boot();
